const emojiCategories=[{name:'Нещодавні',items:['❤️','👍','😂','🔥','🥰','👏','😭','✨']},{name:'Смайли',items:['😀','😃','😄','😁','😆','😅','😂','🤣','😊','😍','😘','🥰','😎','🥳','😢','😭','😡','🤔','😴','🫶']},{name:'Жести',items:['👍','👎','👏','🙏','👋','🤝','💪','✌️','👌','🤟','✍️','🫰']},{name:'Символи',items:['❤️','🩵','🖤','💙','💚','💛','💜','🤍','🔥','✨','⭐','💯','✅','⚡','💬']},{name:'Природа',items:['🐈','🐱','🐼','🐶','🦊','🌙','🌷','🌲','❄️','🌊','☀️','🍁']}];
const emojiSet=new Set(emojiCategories.flatMap(x=>x.items));
const emojiSource=(emoji:string)=>{let points=Array.from(emoji).map(ch=>ch.codePointAt(0)!.toString(16));points=points.filter(x=>x!=='fe0f');return 'https://cdn.jsdelivr.net/gh/twitter/twemoji@14.0.2/assets/svg/'+points.join('-')+'.svg'};
function Emoji({value,style}:{value:string,style:'apple'|'telegram'}){if(style==='apple')return <span className="native-emoji" role="img" aria-label={value}>{value}</span>;return <img className="twemoji" src={emojiSource(value)} alt={value} onError={e=>{const el=e.currentTarget;el.replaceWith(document.createTextNode(value))}}/>}
function TextEmoji({text,style}:{text:string,style:Prefs['emoji_style']}){const chunks=useMemo(()=>{try{return [...new Intl.Segmenter('uk',{granularity:'grapheme'}).segment(text)].map(x=>x.segment)}catch{return Array.from(text)}},[text]);return <>{chunks.map((c,i)=>emojiSet.has(c)?<Emoji key={i} value={c} style={style}/>:<React.Fragment key={i}>{c}</React.Fragment>)}</>}
async function api<T>(url:string, init?:RequestInit):Promise<T>{const res=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(init?.headers||{})},...init});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.detail||`Не вдалося виконати дію (${res.status})`);return data as T}
async function post<T>(url:string,body:unknown){return api<T>(url,{method:'POST',body:JSON.stringify(body)})}
async function patch<T>(url:string,body:unknown){return api<T>(url,{method:'PATCH',body:JSON.stringify(body)})}
function initials(name:string){return(name||'C').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function fmtTime(n?:number){return n?formatDate(n,{hour:'2-digit',minute:'2-digit'}):''}
function isEmojiOnly(text:string){const letters=[...text.trim()];return letters.length>0&&letters.length<=14&&/^[\p{Extended_Pictographic}\uFE0F\u200D\s]+$/u.test(text.trim())}
function readPrefs():Prefs{try{const p={...defaults,...JSON.parse(localStorage.getItem(KEY)||'{}')};if(!(['dark','light','amoled','auto'] as string[]).includes(p.theme))p.theme='dark';return p}catch{return defaults}}
const defaults:Prefs={theme:'dark',accent:'#E11D2E',wallpaper:'w0',font_size:15,compact:false,glass:true,emoji_style:'apple',wall_blur:0,wall_dim:12,animated_wallpaper:true,bubble_style:'rounded',chat_previews:true};


function AvatarCropper({file,onSave,onCancel}:{file:File;onSave:(f:File,url:string)=>void;onCancel:()=>void}){
 const [source,setSource]=useState(''),[zoom,setZoom]=useState(1),[shiftX,setShiftX]=useState(0),[shiftY,setShiftY]=useState(0),[busy,setBusy]=useState(false);
 useEffect(()=>{const url=URL.createObjectURL(file);setSource(url);return()=>URL.revokeObjectURL(url)},[file]);
 async function save(){
  setBusy(true);
  try{
   const img=new Image();img.src=source;await img.decode();
   const side=Math.min(img.naturalWidth,img.naturalHeight)/zoom;
   const dx=(img.naturalWidth-side)/2+(shiftX/100)*(img.naturalWidth-side)/2;
   const dy=(img.naturalHeight-side)/2+(shiftY/100)*(img.naturalHeight-side)/2;
   const x=Math.max(0,Math.min(img.naturalWidth-side,dx));
   const y=Math.max(0,Math.min(img.naturalHeight-side,dy));
   const canvas=document.createElement('canvas');canvas.width=canvas.height=512;
   const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Не вдалося відкрити зображення');
   ctx.drawImage(img,x,y,side,side,0,0,512,512);
   const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(x=>x?resolve(x):reject(new Error('Не вдалося зберегти фото')),'image/webp',.91));
   const output=new File([blob],'cloux-avatar.webp',{type:'image/webp'});
   onSave(output,URL.createObjectURL(blob));
  }catch(e){alert(e instanceof Error?e.message:'Помилка обробки фото')}
  finally{setBusy(false)}
 }
 return <div className="modal-shade" role="dialog" aria-label="Обрізати аватарку"><div className="avatar-crop glass"><div className="modal-title">Обрізати власне фото<button onClick={onCancel}><X/></button></div><div className="crop-stage"><img src={source} style={{transform:`scale(${zoom}) translate(${shiftX/5}%,${shiftY/5}%)`}} alt="Попередній перегляд"/><div className="crop-circle"/></div><label>Масштаб: {zoom.toFixed(1)}×<input type="range" min="1" max="3" step=".1" value={zoom} onChange={e=>setZoom(+e.target.value)}/></label><label>По горизонталі<input type="range" min="-100" max="100" value={shiftX} onChange={e=>setShiftX(+e.target.value)}/></label><label>По вертикалі<input type="range" min="-100" max="100" value={shiftY} onChange={e=>setShiftY(+e.target.value)}/></label><button className="primary full" disabled={!source||busy} onClick={save}>{busy?'Обробляємо…':'Зберегти фото'}</button></div></div>
}
