function Nav({tab,setTab}:{tab:Tab,setTab:(v:Tab)=>void}){const {t}=useI18n();const items=[{id:'chats',icon:MessageCircle,text:t('chats')},{id:'servers',icon:Users,text:t('communities')},{id:'top',icon:Trophy,text:t('top')},{id:'calls',icon:Phone,text:t('calls')},{id:'profile',icon:UserRound,text:t('profile')}] as const;return <nav className="liquid-nav" aria-label="Головні вкладки">{items.map(x=>{const Icon=x.icon;return <button key={x.id} onClick={()=>setTab(x.id)} aria-label={x.text} aria-current={tab===x.id?'page':undefined} className={tab===x.id?'active':''} type="button"><span className="nav-orb"><Icon size={22} strokeWidth={tab===x.id?2.4:1.8}/></span><span>{x.text}</span></button>})}</nav>}
function Leaderboard({me,onOpenUser}:{me:User;onOpenUser:(uid:string)=>void}){const [rows,setRows]=useState<{id:string;username:string;display:string;friends:number}[]>([]),[busy,setBusy]=useState(true),[error,setError]=useState('');const refresh=()=>api<{users:typeof rows}>('/api/friends/leaderboard').then(r=>setRows(r.users)).catch(e=>setError(e instanceof Error?e.message:'Не вдалося завантажити топ')).finally(()=>setBusy(false));useEffect(()=>{refresh()},[]);return <section className="content-screen leaderboard"><header><Trophy/><h2>Топ друзів</h2></header><p>У рейтингу враховуються підтверджені взаємні дружні зв’язки. Відкрий профіль, щоб запропонувати дружбу.</p>{error&&<p className="leaderboard-error">{error}</p>}{busy?<div className="cx-skeleton cx-loading-block"/>:<div className="leaderboard-list">{rows.filter(x=>x.id!==me.id).map((u,i)=><article className="leaderboard-row" key={u.id}><span className="leaderboard-rank">{i+1}</span><span className="leaderboard-avatar">{initials(u.display)}</span><span className="leaderboard-person"><b>{u.display}</b><small>@{u.username} · {u.friends} друзів</small></span><button onClick={()=>onOpenUser(u.id)}>Профіль</button></article>)}</div>}</section>}
type CallLog={chatId:string;title:string;mode:'audio'|'video';at:number;duration:number;result:string};
function CallHub({onStart,onRedial}:{onStart:(mode:'audio'|'video',uid:string)=>void;onRedial:(chatId:string,mode:'audio'|'video')=>void}){const [mode,setMode]=useState<'audio'|'video'|null>(null),[q,setQ]=useState(''),[people,setPeople]=useState<User[]>([]),[logs,setLogs]=useState<CallLog[]>([]),[error,setError]=useState('');useEffect(()=>{let live=true;try{setLogs(JSON.parse(localStorage.getItem('cloux:call-history')||'[]'))}catch{setLogs([])}
 const restore=async()=>{try{const r=await api<{value:{entries?:CallLog[]}}>('/api/cloux/sync/call_history');if(live&&Array.isArray(r.value?.entries)){setLogs(r.value.entries);localStorage.setItem('cloux:call-history',JSON.stringify(r.value.entries))}}catch{}};void restore();
 const fn=(e:Event)=>{const row=(e as CustomEvent<CallLog>).detail;setLogs(prev=>{const next=[row,...prev].slice(0,30);localStorage.setItem('cloux:call-history',JSON.stringify(next));void (async()=>{try{const current=await api<{revision:number,value:{entries?:CallLog[]}}>('/api/cloux/sync/call_history');const entries=[row,...(Array.isArray(current.value?.entries)?current.value.entries:prev).filter(x=>x.at!==row.at)].slice(0,30);await api('/api/cloux/sync/call_history',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({value:{entries},expected_revision:current.revision})})}catch{}})();return next})};
 window.addEventListener('cloux:call-log',fn);return()=>{live=false;window.removeEventListener('cloux:call-log',fn)}},[]);useEffect(()=>{if(!mode||q.trim().length<2){setPeople([]);return}const t=setTimeout(()=>api<{users:User[]}>('/api/users?q='+encodeURIComponent(q)).then(x=>setPeople(x.users)).catch(e=>setError(e instanceof Error?e.message:'Спробуй ще раз')),250);return()=>clearTimeout(t)},[mode,q]);return <section className="content-screen call-hub"><header><Phone/><h2>Дзвінки</h2></header><p>Почни голосовий або відеодзвінок із контактом Cloux.</p><div className="call-quick"><button onClick={()=>{setMode('audio');setQ('')}}><Phone/><b>Голосовий дзвінок</b><small>Чистий звук через WebRTC</small></button><button onClick={()=>{setMode('video');setQ('')}}><Video/><b>Відеодзвінок</b><small>Камера та демонстрація екрана</small></button></div>{mode&&<div className="call-contact-picker"><div className="call-picker-title">{mode==='audio'?'Кому подзвонити?':'З ким увімкнути відео?'}<button onClick={()=>setMode(null)}><X/></button></div><input autoFocus placeholder="Знайти за ім’ям або @нікнеймом" value={q} onChange={e=>setQ(e.target.value)}/>{error&&<p>{error}</p>}{people.map(p=><button className="call-contact" key={p.id} onClick={()=>{setMode(null);onStart(mode,p.id)}}><Avatar name={p.display}/><span><b>{p.display}</b><small>@{p.username}</small></span><Phone size={18}/></button>)}</div>}<h3>Останні дзвінки</h3>{logs.length?logs.map((x,i)=><article className="call-log" key={i}><span className="call-log-icon"><Phone size={18}/></span><span><b>{x.title}</b><small>{x.result} · {x.mode==='video'?'відео':'голосовий'} · {new Date(x.at).toLocaleString('uk-UA',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</small></span><button className="call-redial" aria-label={'Передзвонити '+x.title} disabled={!x.chatId} onClick={()=>onRedial(x.chatId,x.mode)}><Phone size={17}/></button><small>{Math.floor(x.duration/60)}:{String(x.duration%60).padStart(2,'0')}</small></article>):<div className="cx-elegant-empty"><span className="cx-empty-orbit"><Phone size={36}/><span className="cx-orbit-dot"/></span><h3>Перший дзвінок починається тут</h3><p>Подзвони другові — і всі останні дзвінки з’являться на цьому екрані.</p><button onClick={()=>{setMode("audio");setQ("")}}><Phone size={18}/> Обрати співрозмовника</button></div>}</section>}
