type ServerInfo={server:{id:string;name:string;description:string;role:string;invite_code:string|null};channels:{id:string;title:string;kind:string}[];members:{id:string;display:string;username:string;role:string;online:boolean}[]};
function ServerSpace({servers,onCreate,onOpenChat}:{servers:ServerSummary[];onCreate:()=>void;onOpenChat:(id:string)=>void}){const [selected,setSelected]=useState<string|null>(null),[data,setData]=useState<ServerInfo|null>(null),[error,setError]=useState(''),[channelName,setChannelName]=useState(''),[busy,setBusy]=useState(false);useEffect(()=>{if(!selected){setData(null);return}let alive=true;api<ServerInfo>('/api/servers/'+encodeURIComponent(selected)).then(x=>{if(alive)setData(x)}).catch(e=>{if(alive)setError(e instanceof Error?e.message:'Не вдалося завантажити спільноту')});return()=>{alive=false}},[selected]);async function createChannel(){if(!selected||channelName.trim().length<2)return;setBusy(true);try{await post('/api/servers/'+encodeURIComponent(selected)+'/channels',{name:channelName.trim()});setChannelName('');const x=await api<ServerInfo>('/api/servers/'+encodeURIComponent(selected));setData(x)}catch(e){setError(e instanceof Error?e.message:'Не вдалося створити канал')}finally{setBusy(false)}}return <section className="content-screen server-space"><header><ServerIcon/><h2>Спільноти</h2></header>{error&&<p role="alert" className="leaderboard-error">{error}</p>}{!selected?<><p>Твої сервери та текстові канали.</p><div className="server-list">{servers.map(s=><button className="server-row" key={s.id} onClick={()=>{setError('');setSelected(s.id)}}><ServerIcon size={20}/><span><b>{s.name}</b><small>{s.member_count} учасників · роль: {s.role}</small></span><ChevronRight/></button>)}</div><button className="primary" onClick={onCreate}><Plus size={18}/> Створити спільноту</button>{servers.length===0&&<p className="muted">Тут з’являться спільноти, до яких ти приєднаєшся.</p>}</>:!data?<p>Завантажуємо спільноту…</p>:<><button className="server-back" onClick={()=>{setSelected(null);setError('')}}><ArrowLeft size={18}/> Усі спільноти</button><h3>{data.server.name}</h3><p>{data.server.description||`${data.members.length} учасників`}</p>{data.server.invite_code&&<button className="upload-wall" onClick={()=>void navigator.clipboard.writeText(data.server.invite_code||'').then(()=>setError('Код-запрошення скопійовано.')).catch(()=>setError('Не вдалося скопіювати код-запрошення.'))}><Copy size={18}/> Скопіювати код-запрошення</button>}<h3>Текстові канали</h3><div className="server-list">{data.channels.map(ch=><button className="server-row" key={ch.id} onClick={()=>onOpenChat(ch.id)}><MessageCircle size={18}/><b># {ch.title}</b><ChevronRight/></button>)}{!data.channels.length&&<p className="muted">У цій спільноті поки немає каналів.</p>}</div>{['owner','admin'].includes(data.server.role)&&<div className="inline-form"><input maxLength={65} value={channelName} onChange={e=>setChannelName(e.target.value)} placeholder="Назва нового каналу" onKeyDown={e=>{if(e.key==='Enter')void createChannel()}}/><button className="primary" disabled={busy||channelName.trim().length<2} onClick={()=>void createChannel()}><Plus size={17}/> Додати</button></div>}<h3>Учасники</h3><div className="server-list">{data.members.map(m=><div className="server-member" key={m.id}><Avatar name={m.display}/><span><b>{m.display}</b><small>@{m.username} · {m.role==='owner'?'власник':m.role==='admin'?'адмін':'учасник'}</small></span><i className={m.online?'online':''} title={m.online?'У мережі':'Не в мережі'}/></div>)}</div></>}</section>}
