 async function createEntity(kind:'group'|'server'){setShowCreate(false);const title=prompt(kind==='group'?'Назва групи:':kind==='server'?'Назва сервера:':'Назва каналу:');if(!title?.trim())return;try{if(kind==='server'){await post('/api/servers',{name:title.trim()});const r=await api<{servers:ServerSummary[]}>('/api/servers');setServers(r.servers);setTab('servers')}else{const r=await post<{chat_id:string}>('/api/groups',{title:title.trim(),members:[]});const next=await api<{chats:Chat[]}>('/api/chats');setChats(next.chats);setActive(r.chat_id);setTab('chats')}}catch(e){setError(e instanceof Error?e.message:'Не вдалося створити. Спробуй ще раз.')}}
